Let $\mathcal{U}_2,\cdots,\mathcal{U}_{p}$ be pairwise disjoint finite index sets (could be empty), $|\mathcal{U}_j|\leq D$. Given $\zeta_j\in\{\pm\}$ for $1\leq j\leq p$ and $\zeta_{\mathfrak{l}}\in\{\pm\}$ for any $\mathfrak{l}\in\mathcal{U}_j$, and $N_j$ for $2\leq j\leq p$ and $N_{\mathfrak{l}}$ for any $\mathfrak{l}\in\mathcal{U}_j$, let $N_*=\max(N_2,\cdots,N_{p})$, and define $\zeta_{\mathfrak{l}}^*=\zeta_{\mathfrak{l}}\zeta_j$ for $\mathfrak{l}\in\mathcal{U}_j$. Assume that \[\sum_{j=1}^p\zeta_j=1,\quad N_j^\delta\leq N_{\mathfrak{l}}\leq N_j\,(\forall \mathfrak{l}\in \mathcal{U}_j,\,2\leq j\leq p).\]  Assume there are some pairings in $\mathcal{W}:=\mathcal{U}_2\cup\cdots\cup\mathcal{U}_{p}$ (i.e. a collection of pairwise disjoint two-element subsets of $\mathcal{W}$, each containing two elements from two different $\mathcal{U}_j$), such that for any pair $(\mathfrak{l},\mathfrak{l}')$ we have $\zeta_{\mathfrak{l}'}^*=-\zeta_{\mathfrak{l}}^*$ and $N_{\mathfrak{l}'}=N_{\mathfrak{l}}$. Let $h^{(j)}=h_{k_jk_{\mathcal{U}_j}}^{(j)}$, where $2\leq j\leq p$, be tensors, and $h=h_{kk_1\cdots k_p}$ be a tensor supported in $\langle k_j\rangle\leq N_j$ for $2\leq j\leq p$. Let the set of paired elements in $\mathcal{W}$ be $\mathcal{Q}$ and the set of unpaired elements be $\mathcal{U}$, define the semi-product
\begin{equation}H=H_{kk_1k_{\mathcal{U}}}=\sum_{k_2,\cdots,k_{p}}\sum_{k_{\mathcal{Q}}}h_{kk_1\cdots k_p}\prod_{j=2}^{p}\big(h_{k_jk_{\mathcal{U}_j}}^{(j)}\big)^{\zeta_j},\end{equation} where the sum is taken over all $(k_2,\cdots,k_{p})$ and $k_{\mathcal{Q}}$ that satisfy $k_{\mathfrak{l}'}=k_{\mathfrak{l}}$ for any pairing $(\mathfrak{l},\mathfrak{l}')$.

For each $2\leq j\leq p$, in the support of $h^{(j)}$ we assume that $k_{\mathfrak{l}}\in\mathbb{Z}^d$, $\langle k_j\rangle\leq N_j$ and $N_{\mathfrak{l}}/2<\langle k_{\mathfrak{l}}\rangle\leq N_{\mathfrak{l}}$ for each $\mathfrak{l}\in\mathcal{U}_j$. Moreover, $h^{(j)}$ has one of the following three types:
\begin{enumerate}
\item Type $R0$: where we assume, in the support of $h^{(j)}$, that
\begin{equation}\sum_{\mathfrak{l}\in \mathcal{U}_j}\zeta_{\mathfrak{l}}=1,\quad k_j=\sum_{\mathfrak{l}\in\mathcal{U}_j}\zeta_{\mathfrak{l}} k_{\mathfrak{l}},\quad |k_j|^2-\sum_{\mathfrak{l}\in\mathcal{U}_j}\zeta_{\mathfrak{l}} |k_{\mathfrak{l}}|^2=\Gamma_j.
\end{equation} Moreover, for any partition $(P_j,Q_j)$ of $\mathcal{U}_j$, we assume
\begin{equation}\|h^{(j)}\|_{k_jk_{P_j}\to k_{Q_j}}\leq \mathfrak{X}_j\cdot \prod_{\mathfrak{l}\in \mathcal{U}_j}N_{\mathfrak{l}}^{\beta_1}\cdot\mathcal{Z}_{0,j}\mathcal{Z}_{1,j},
\end{equation}where $\mathcal{Z}_{0,j}$ and $\mathcal{Z}_{1,j}$ are defined similarly as in (5.33) but with the following modifications,
 \begin{equation}\mathcal{Z}_{0,j}=\left\{
  \begin{aligned}&\big(\max_{\mathfrak{l}\in Q_j}N_{\mathfrak{l}}\big)^{-\beta_1},&&\mathrm{if\ }Q_j\neq\varnothing;\\
    & \big(\min_{\mathfrak{l}\in\mathcal{U}_j}N_{\mathfrak{l}}\big)^{\frac{d}{2}-\beta_1},&&\mathrm{if\ }Q_j=\varnothing,
 \end{aligned}
 \right.\qquad\mathcal{Z}_{1,j}=\left\{
 \begin{aligned}&1,&{\rm{if }}\max_{\mathfrak{l}\in \mathcal{U}_j}N_{\mathfrak{l}}&\geq (10^3dp)^{-D}N_j;\\
&N_j^{-4\varepsilon},&{\rm{if }}\max_{\mathfrak{l}\in \mathcal{U}_j}N_{\mathfrak{l}}&< (10^3dp)^{-D}N_j.
 \end{aligned}
 \right.
 \end{equation}

 \item Type $R0^+$: similar to type $R0$, but instead of (6.10), in the support of $h^{(j)}$ we only assume that 
\begin{equation}
 k_j-\sum_{\mathfrak{l}\in\mathcal{U}_j}k_{\mathfrak{l}}=m_j\end{equation} for some given $m_j\in \mathbb{Z}^d$. Moreover the bounds (6.11)--(6.12) also hold (in particular $\mathcal{Z}_{1,j}=N_j^{-4\varepsilon}$ if $\mathcal{U}_j=\varnothing$), except that in (6.12), when $Q_j=\varnothing$, we have $\mathcal{Z}_{0,j}=1$ instead of $(\min_{\mathfrak{l}\in\mathcal{U}_j}N_{\mathfrak{l}})^{d/2-\beta_1}$.

\item Type $R1$: where we assume, in the support of $h^{(j)}$, that
\begin{equation}\bigg|k_j-\sum_{\mathfrak{l}\in\mathcal{U}_j}\zeta_{\mathfrak{l}} k_{\mathfrak{l}}-m_j\bigg|\leq (N_*)^{3\delta}
\end{equation} for some given $m_j\in \mathbb{Z}^d$. Moreover, for any partition $(P_j,Q_j)$ of $\mathcal{U}_j$ we have
\begin{equation}\|h^{(j)}\|_{k_jk_{P_j}\to k_{Q_j}}\leq
\left\{
\begin{aligned}&\mathfrak{X}_j\cdot \prod_{\mathfrak{l}\in \mathcal{U}_j}N_{\mathfrak{l}}^\beta\cdot \big(\max_{\mathfrak{l}\in Q_j}N_{\mathfrak{l}}\big)^{-\beta},&Q_j&\neq\varnothing;\\
&\mathfrak{X}_j\cdot \prod_{\mathfrak{l}\in \mathcal{U}_j}N_{\mathfrak{l}}^\beta\cdot N_j^{-\varepsilon},&Q_j&=\varnothing.
\end{aligned}
\right. 
\end{equation}
\end{enumerate} Regarding the tensor $h$, we assume that $|h_{kk_1\cdots k_p}|\lesssim 1$, and that $h=h_{kk_1\cdots k_p}$ is supported in the set
\begin{equation}
k=\sum_{j=1}^{p}\zeta_jk_j,\quad |k|^2-\sum_{j=1}^p\zeta_j|k_j|^2=\Gamma,
\end{equation} and that any pairing in $(k,k_1,\cdots,k_p)$ must be over-paired.

Then, for any partition $(P,Q)$ of $\mathcal{U}$, we have the bound
\begin{equation}\prod_{\mathfrak{l}\in\mathcal{Q}}N_{\mathfrak{l}}^{-\alpha+4\varepsilon+\theta}\cdot\|H\|_{kk_P\to k_1k_Q}\lesssim\prod_{j=2}^{p}\mathfrak{X}_j\cdot\prod_{\mathfrak{l}\in\mathcal{U}}N_{\mathfrak{l}}^\beta\cdot\prod_{j}^{(0,0^+)}N_j^{-2\varepsilon}\cdot(N_*)^{-\varepsilon^3},
\end{equation} where the product $\prod_{j}^{(0,0^+)}$ is taken over all $2\leq j\leq p$ such that $h^{(j)}$ is of type $R0$ or type $R0^+$. The result is uniform in all parameters $\Gamma, \Gamma_j,m_j$ etc., and remains true if we replace $p$ by an odd $3\leq q\leq p$.  It also remains true if instead of the second equation in the support condition in (6.16), we assume that $h$ satisfies (4.27).
  }}}

Consider the same setting as in Proposition 6.2. Here we assume that each $h^{(j)}$ has type $R0$ or $R0^+$ (in the sense of Proposition 6.2), but in both cases the factor $\mathcal{Z}_{1,j}$ in (6.11) is replaced by 1 (the factor $\mathcal{Z}_{0,j}$ remains the same). Then we have
\begin{equation}\prod_{\mathfrak{l}\in\mathcal{Q}}N_{\mathfrak{l}}^{-\alpha+8\varepsilon+\theta}\cdot\|H\|_{kk_P\to k_1k_Q}\lesssim\prod_{j=2}^{p}\mathfrak{X}_j\cdot\prod_{\mathfrak{l}\in\mathcal{U}}N_{\mathfrak{l}}^{\beta_1}\cdot \big(\max_{2\leq j\leq p}\max_{\mathfrak{l}\in\mathcal{U}_j}N_{\mathfrak{l}}\big)^{-4p\varepsilon}.
\end{equation} The same holds if $p$ is replaced by odd $3\leq q\leq p$, without changing the power $4p\varepsilon$ in (6.37).

Let $3\leq q\leq p$ be odd, $0\leq r\leq q$, and let $\mathcal{S}_j\,(1\leq j\leq r)$ be regular plants with frequency $N(\mathcal{S}_j)=N_j\leq M$ and $|\mathcal{S}_j|\leq D$. Fix  $N_j\leq M/2$ for $r+1\leq j\leq q$ and $\zeta_j\in\{\pm\}$ for $1\leq j\leq q$, and assume that $\sum_{j=1}^q\zeta_j=1$. Denote $\mathscr{B}=(M,q,r,\zeta_1,\cdots,\zeta_q,N_1,\cdots,N_q)$. Let $h=h_{kk_1\cdots k_q}(\lambda_{r+1},\cdots,\lambda_q)$ be a constant tensor\footnote{i.e. which does not depend on $\omega$.} supported in the set \begin{equation}
\begin{aligned}\langle k\rangle&\leq M,&\langle k_j\rangle&\leq N_j\,(1\leq j\leq q),\quad\langle\lambda_j\rangle\leq 2M^{\kappa^2}\,(r+1\leq j\leq q),\\
k&=\sum_{j=1}^q\zeta_jk_j,&\bigg||k|^2&-\sum_{j=1}^q\zeta_j|k_j|^2+\sum_{j=r+1}^q\zeta_j\lambda_j+\widetilde{\Gamma}\bigg|\lesssim 1,
\end{aligned}\end{equation} where $\widetilde{\Gamma}\in\mathbb{Z}$ is fixed. Assume that
\begin{equation}|h|+|\partial_{\lambda_j}h|\lesssim \tau^{-\theta},\quad r+1\leq j\leq q,
\end{equation} 
and that any pairing in $(k,k_1,\cdots,k_q)$ must be over-paired.
Now let $h^{(j)}=h_{k_jk_{\mathcal{U}_j}}^{(j)}(k_{\mathcal{V}_j},\lambda_{\mathcal{V}_j})$ be an $\mathcal{S}_j$-tensor for $1\leq j\leq r$, $\mathscr{O}$ be as in Definition 3.6, and let
\begin{equation}
\begin{aligned}\mathcal{S}&=(\mathcal{L},\mathcal{V},\mathcal{Y})=\mathtt{Trim}(\mathtt{Merge}(\mathcal{S}_1,\cdots,\mathcal{S}_r,\mathscr{B},\mathscr{O}),M^\delta),\\
H&=\mathtt{Trim}(\mathtt{Merge}(h^{(1)},\cdots,h^{(r)},h,\mathscr{B},\mathscr{O}),M^\delta).
\end{aligned}
\end{equation} 
Let $N_*:=\max(N_2,\cdots,N_{q})$, assume $N_*\geq M^\delta$, and $\Upsilon$ be a factor such that
\begin{equation}
\Upsilon\leq \tau^{-\theta};\qquad \Upsilon\leq \tau^{-\theta}M^{-40dp\varepsilon}\,\,\,\mathrm{if}\,\,\,\max_{1\leq j\leq q}N_j\leq (50dp)^{-1}M.
\end{equation}
We assume that the tensor $h^{(1)}$ is $\mathcal{B}_{M^{[\delta]}}$ measurable, and $N_{\mathfrak{l}}\geq M^\delta$ for $\mathfrak{l}\in\mathcal{L}_1$; for $2\leq j\leq r$, the tensor $h^{(j)}$ is $\mathcal{B}_{(N_*)^{[\delta]}}$ measurable, and $N_{\mathfrak{l}}\geq (N_*)^\delta$ for $\mathfrak{l}\in\mathcal{L}_j$.
Furthermore we assume that for $1\leq j\leq r$, $\mathcal{S}_j$ and $h^{(j)}$ have one of the following two types:

(1) Type 0: where $\mathcal{V}_j=\varnothing$, and in the support of $h^{(j)}$ we have
\begin{equation}\sum_{\mathfrak{l}\in\mathcal{U}_j}\zeta_{\mathfrak{l}}=1,\quad k_j=\sum_{\mathfrak{l}\in\mathcal{U}_j}\zeta_{\mathfrak{l}} k_{\mathfrak{l}},\quad |k_j|^2-\sum_{\mathfrak{l}\in\mathcal{U}_j}\zeta_{\mathfrak{l}}|k_{\mathfrak{l}}|^2=\Gamma_j,
\end{equation} where $\Gamma_j\in\mathbb{Z}$ is fixed, and $h^{(j)}$ satisfies the bound
\begin{equation}\|h^{(j)}\|_{k_jk_{B_j}\to k_{C_j}}\lesssim\mathfrak{X}_j\cdot\tau^{-\theta}\prod_{\mathfrak{l}\in B_j\cup C_j} N_{\mathfrak{l}}^{\beta_1}\prod_{\mathfrak{l}\in\mathcal{P}_j}N_{\mathfrak{l}}^{-8\varepsilon}\prod_{\mathfrak{l}\in E_j}N_{\mathfrak{l}}^{4\varepsilon}\prod_{\mathfrak{p}\in\mathcal{Y}_j}N_{\mathfrak{p}}^{-\delta^3}\cdot\mathcal{X}_{0,j}\mathcal{X}_{1,j},
\end{equation} for any subpartition $(B_j,C_j)$ of $\mathcal{U}_j$, where $E_j=\mathcal{U}_j\backslash(B_j\cup C_j)$, and $\mathcal{X}_{0,j}$ and $\mathcal{X}_{1,j}$ are defined as in (5.33) but are associated with $\mathcal{S}_j$ and $(B_j,C_j)$ instead.

(2) Type 1: where $h^{(j)}$ satisfies the bounds (with $B_j,C_j,E_j$ same as (1)) \begin{equation}\|h^{(j)}\|_{X_{\mathcal{V}_j}^{-b_0}[k_jk_{B_j}\to k_{C_j}]}\lesssim\mathfrak{X}_j\cdot\tau^{-\theta}\prod_{\mathfrak{l}\in B_j\cup C_j}N_{\mathfrak{l}}^\beta\prod_{\mathfrak{l}\in\mathcal{P}_j}N_{\mathfrak{l}}^{-4\varepsilon}\prod_{\mathfrak{l}\in E_j}N_{\mathfrak{l}}^{8\varepsilon}\prod_{\mathfrak{p}\in\mathcal{Y}_j}N_{\mathfrak{p}}^{-\delta^3} \prod_{\mathfrak{f} \in \mathcal{V}_j} N_{\mathfrak{f}}^d\cdot \big(\max_{\mathfrak{l}\in C_j}N_{\mathfrak{l}}\big)^{-\beta},\quad \mathrm{if\ }C_j\neq\varnothing,
 \end{equation} 
 \begin{equation}
 \|h^{(j)}\|_{X_{\mathcal{V}_j}^{-b_0}[k_jk_{B_j}]}\lesssim\mathfrak{X}_j\cdot\tau^{-\theta}\prod_{\mathfrak{l}\in B_j}N_{\mathfrak{l}}^\beta\prod_{\mathfrak{l}\in\mathcal{P}_j}N_{\mathfrak{l}}^{-4\varepsilon}\prod_{\mathfrak{l}\in E_j}N_{\mathfrak{l}}^{8\varepsilon}\prod_{\mathfrak{p}\in\mathcal{Y}_j}N_{\mathfrak{p}}^{-\delta^3}\prod_{\mathfrak{f} \in \mathcal{V}_j} N_{\mathfrak{f}}^d\cdot N_j^{-\varepsilon},\quad\mathrm{if\ }C_j=\varnothing;
 \end{equation} and we also assume for $C_j=\varnothing$ the localization bound
 \begin{equation} \bigg\|\bigg(1+\frac{1}{R_j}\big|k_j-\sum_{\mathfrak{l}\in\mathcal{U}_j}\zeta_{\mathfrak{l}} k_{\mathfrak{l}}-\ell_j\big|\bigg)^\kappa h^{(j)}\bigg\|_{X^{-b_0}_{\mathcal{V}_j}[k_jk_{B_j}]}\lesssim\mathfrak{X}_j\cdot \tau^{-\theta}\prod_{\mathfrak{l}\in B_j}N_{\mathfrak{l}}^\beta\prod_{\mathfrak{l}\in\mathcal{P}_j}N_{\mathfrak{l}}^{-4\varepsilon}\prod_{\mathfrak{l}\in E_j}N_{\mathfrak{l}}^{8\varepsilon}\prod_{\mathfrak{p}\in\mathcal{Y}_j}N_{\mathfrak{p}}^{-\delta^3}\prod_{\mathfrak{f} \in \mathcal{V}_j} N_{\mathfrak{f}}^d,
 \end{equation} where $R_1=M^{2\delta}$, $R_j=(N_*)^{2\delta}$ for $j\geq 2$ and $\ell_j=\sum_{\mathfrak{f}\in\mathcal{V}_j}\zeta_{\mathfrak{f}} k_{\mathfrak{f}}$, and the $\lambda_{\mathcal{V}_j}$-derivative bound (for $C_j=E_j=\varnothing$),
  \begin{equation} \|\partial_{\lambda_{\mathcal{V}_j}}h^{(j)}\|_{X_{\mathcal{V}_j}^{-b_0}[k_jk_{\mathcal{U}_j}]}\lesssim \mathfrak{X}_j\cdot\tau^{-\theta}\exp[(\log N_j)^5+|\mathcal{S}_j|(\log N_j)^3].
 \end{equation}

 Finally fix a subpartition $(B,C)$ of $\mathcal{U}$, and let $E=\mathcal{U}\backslash(B\cup C)$.
Then, under all of the above assumptions, we have the following results, where we denote
 \begin{equation}\mathfrak{Y}=\prod_{j=1}^r\mathfrak{X}_j\cdot\tau^{-\theta}M^{\theta}(N_*)^{-2\varepsilon^4}:
 \end{equation}

(i) If $C\neq\varnothing$, and assume that $\max\{N_{\mathfrak{l}}:\mathfrak{l}\in C\cap\mathcal{U}_1\}\sim\max\{N_{\mathfrak{l}}:\mathfrak{l}\in C\}$, then $\tau^{-1}M$-certainly, the tensor $H=H_{kk_{\mathcal{U}}}(k_{\mathcal{V}},\lambda_{\mathcal{V}})$ satisfies the bounds \begin{equation}\sqrt{\Upsilon}\cdot\|H\|_{X_{\mathcal{V}}^{-b_0}[kk_{B}\to k_{C}]}\lesssim\mathfrak{Y}\cdot\tau^{-\theta}\prod_{\mathfrak{l}\in B\cup C}N_{\mathfrak{l}}^\beta\prod_{\mathfrak{l}\in\mathcal{P}}N_{\mathfrak{l}}^{-4\varepsilon}\prod_{\mathfrak{l}\in E}N_{\mathfrak{l}}^{8\varepsilon}\prod_{\mathfrak{p}\in\mathcal{Y}}N_{\mathfrak{p}}^{-\delta^3} \prod_{\mathfrak{f} \in \mathcal{V}} N_{\mathfrak{f}}^d\cdot \big(\max_{\mathfrak{l}\in C}N_{\mathfrak{l}}\big)^{-\beta}.
 \end{equation}

(ii) If $C=\varnothing$, and assume that $h^{(1)}$ has type 1, and $N_1\gtrsim N_j$ for all $1\leq j\leq r$ such that $h^{(j)}$ has type 1, then $\tau^{-1}M$-certainly we have  \begin{equation}  \sqrt{\Upsilon}\cdot\|H\|_{X_{\mathcal{V}}^{-b_0}[kk_{B}]}\lesssim\mathfrak{Y}\cdot\tau^{-\theta}\prod_{\mathfrak{l}\in B}N_{\mathfrak{l}}^\beta\prod_{\mathfrak{l}\in\mathcal{P}}N_{\mathfrak{l}}^{-4\varepsilon}\prod_{\mathfrak{l}\in E}N_{\mathfrak{l}}^{8\varepsilon}\prod_{\mathfrak{p}\in\mathcal{Y}}N_{\mathfrak{p}}^{-\delta^3}\prod_{\mathfrak{f} \in \mathcal{V}} N_{\mathfrak{f}}^d\cdot M^{-\varepsilon}.
 \end{equation}

 (iii) If $C=\varnothing$, and assume that $h^{(1)}$ has type 1. Moreover, assume we restrict the tensors $H_{kk_{\mathcal{U}}}(k_{\mathcal{V}},\lambda_{\mathcal{V}})$ and $h_{k_1k_{\mathcal{U}_1}}^{(1)}(k_{\mathcal{V}_1},\lambda_{\mathcal{V}_1})$ to the sets
 \begin{equation}
 1+\frac{1}{M^{2\delta}}\bigg|k-\sum_{\mathfrak{l}\in\mathcal{U}}\zeta_{\mathfrak{l}}^* k_{\mathfrak{l}}-\ell\bigg|\sim K,\quad 1+\frac{1}{M^{2\delta}}\bigg|k_1-\sum_{\mathfrak{l}\in\mathcal{U}_1}\zeta_{\mathfrak{l}} k_{\mathfrak{l}}-\ell_1\bigg|\sim K_1,\end{equation} where $K\lesssim K_1$ are two dyadic numbers, $\zeta_{\mathfrak{n}}^*$ represents the sign of $\mathfrak{n}$ in $\mathcal{S}$, $\ell=\sum_{\mathfrak{f}\in\mathcal{V}}\zeta_{\mathfrak{f}}^* k_{\mathfrak{f}}$, and $\ell_1=\sum_{\mathfrak{f}\in\mathcal{V}_1}\zeta_{\mathfrak{f}} k_{\mathfrak{f}}$ as above. Then $\tau^{-1}M$-certainly we have  \begin{equation} \sqrt{\Upsilon}\cdot\bigg\|\bigg(1+\frac{1}{M^{2\delta}}\big|k-\sum_{\mathfrak{l}\in\mathcal{U}}\zeta_{\mathfrak{l}}^* k_{\mathfrak{l}}-\ell\big|\bigg)^\kappa H\bigg\|_{X_{\mathcal{V}}^{-b_0}[kk_{B}]}\lesssim\mathfrak{Y}\cdot \tau^{-\theta}\prod_{\mathfrak{l}\in B}N_{\mathfrak{l}}^\beta\prod_{\mathfrak{l}\in\mathcal{P}}N_{\mathfrak{l}}^{-4\varepsilon}\prod_{\mathfrak{l}\in E}N_{\mathfrak{l}}^{8\varepsilon}\prod_{\mathfrak{p}\in\mathcal{Y}}N_{\mathfrak{p}}^{-\delta^3} \prod_{\mathfrak{f} \in \mathcal{V}} N_{\mathfrak{f}}^d.
 \end{equation}

Let $3\leq q\leq p$ be odd and $1\leq r\leq q$. For $2\leq j\leq r$, assume that $\Psi_{k_j}^{(j)}=\Psi_{k_j}[\mathcal{S}_j,h^{(j)}]$ as in (3.8), where $\mathcal{S}_j$ is a regular plant with $|\mathcal{S}_j|\leq D$ and $N(\mathcal{S}_j)=N_j\leq M$ such that $N_{\mathfrak{l}}\geq M^\delta$ for each $\mathfrak{l}\in\mathcal{L}_j$, $h^{(j)}$ is an $\mathcal{S}_j$-tensor that is $\mathcal{B}_{M^{[\delta]}}$ measurable. Moreover we assume that $h^{(j)}$ either has type 0 and satisfies the assumptions of Proposition 6.4 (1), or has type 1 and satisfies the assumptions of Proposition 6.4 (2).

We also fix $\zeta_j\,(1\leq j\leq q)$ and $N_j\leq M/2\,(r+1\leq j\leq q)$, and assume that $\max(N_2,\cdots,N_q)=M$. Let $h=h_{kk_1\cdots k_q}(\lambda_{r+1},\cdots,\lambda_q)$ be a constant tensor (which does not depend on $\omega$) supported in the set \begin{equation}
\langle k_j\rangle\leq N_j\,(2\leq j\leq q),\quad\langle\lambda_j\rangle\leq 2M^{\kappa^2}\,(r+1\leq j\leq q),\quad k=\sum_{j=1}^q\zeta_jk_j;
\end{equation} also assume that $h$ \emph{can be written as a function of\footnote{We may also need to multiply this $h$ by functions $\mathbf{1}_{\langle k\rangle\geq M^2}$ or $\mathbf{1}_{\langle k_1\rangle\geq M^2}$, but they do not affect Proposition 4.15 (which can be easily checked), so the proof below will proceed in the same way.} $k-\zeta_1k_1$, $|k|^2-\zeta_1|k_1|^2$, and $(k_2,\cdots,k_q,\lambda_{r+1},\cdots,\lambda_q)$}, and satisfies that
\begin{equation}|h|+|\partial_{\lambda_j}h|\lesssim \frac{\tau^{-\theta}}{\langle\Omega+
\zeta_{r+1}\lambda_{r+1}+\cdots+\zeta_q\lambda_q+\widetilde{\Xi}\rangle},\quad r+1\leq j\leq q,
\end{equation}where $\Omega=|k|^2-\sum_{j=1}^q\zeta_j|k_j|^2$, $\widetilde{\Xi}\in\mathbb{R}$ is fixed with $|\widetilde{\Xi}|\lesssim M^{\kappa^2}$, and that any pairing in $(k,k_1,\cdots,k_q)$ must be over-paired.
Now define 
\begin{equation}\mathscr{M}_{kk_1}=\sum_{k_2,\cdots,k_q}\int\mathrm{d}\lambda_{r+1}\cdots\mathrm{d}\lambda_q\cdot h_{kk_1\cdots k_q}(\lambda_{r+1},\cdots,\lambda_q)\prod_{j=2}^r(\Psi_{k_j}^{(j)})^{\zeta_j}\prod_{j=r+1}^q(\widehat{z_{N_j}})_{k_j}^{\zeta_j}(\lambda_j),
\end{equation} possibly with Fourier truncations on $z_{N_j}$ as in part (5) of Proposition 5.1, then $\tau^{-1}M$-certainly we have
\begin{equation}\|\mathscr{M}_{kk_1}\|_{k\to k_1}\leq\prod_{j=2}^r\mathfrak{X}_j\cdot\tau^{-\theta}M^{-\varepsilon^4}.
\end{equation}

Fix $s>s_{pr}$ and $\alpha$ as in (1.3), and let $f(\omega)$ be as in (1.2). Let $u_N$ be the solution to the canonically truncated system \begin{equation}
\left\{
\begin{aligned}(i\partial_t+\Delta)u_N&=\Pi_NW_N^{p}(u_N),\\
u_N(0)&=\Pi_Nf(\omega).
\end{aligned}
\right.
\end{equation} Then, for $0<\tau\ll 1$, there exists a set $Z\subset\Theta$ with $\mathbb{P}(Z)\leq C_\theta e^{-\tau^{-\theta}}$, where $\theta$ is a small constant (ultimately determined by $(d,p,s)$, and independent of $\tau$) and $C_\theta$ is a constant determined by $\theta$, such that when $\omega\not\in Z$, the sequence $\{u_N\}$ converges, as $N\to\infty$, to a unique limit $u$ in $C_t^0H_x^{s-}[-\tau,\tau]$.

Moreover, for this $u$, the nonlinearity $W^p(u)$ in (1.1), which is the Wick ordering of $|u|^{p-1}u$, is well-defined as
\begin{equation}W^p(u)=\lim_{N\to\infty}W_N^p(\Pi_Nu)=\lim_{N\to\infty}\Pi_NW_N^p(\Pi_Nu)
\end{equation} in the sense of spacetime distributions (where both limits exist and are equal), and $u$ solves the equation (1.1) in the distributional sense. Finally this solution $u$ has an explicit expansion in terms of multilinear Gaussians with adapted random tensor coefficients; see (8.5) for the precise form.
}

Fix $(s,\alpha)$ and $f_{\mathrm{ho}}(\omega)$ as in (1.10), and $0<\nu<(p-1)(s-s_{pr})$. Let $u_{\mathrm{ho}}$ be the solution to the system \begin{equation}
\left\{
\begin{aligned}(i\partial_T+\Delta)u_{\mathrm{ho}}&=|u_{\mathrm{ho}}|^{p-1}u_{\mathrm{ho}},\\
u_{\mathrm{ho}}(0)&=f_{\mathrm{ho}}(\omega).
\end{aligned}
\right.
\end{equation} Then there exists a set $Z\subset\Theta$ with $\mathbb{P}(Z)\leq C_\theta e^{-N^\theta}$, where $\theta$ is a small constant (ultimately determined by $(d,p,s)$, and independent of $N$) and $C_\theta$ is a constant determined by $\theta$, such that when $\omega\not\in Z$, the solution $u_{\mathrm{ho}}$ exists up to time $T=N^\nu$. Moreover, for some real valued gauge function $B(T)$, we have
\begin{equation}\sup_{0\leq T\leq N^\nu}\|u_{\mathrm{ho}}(T)-e^{-iB(T)}e^{iT\Delta}u_{\mathrm{ho}}(0)\|_{H^s}\leq N^{-\theta}.
\end{equation}
}
